    28→/**
    29→ * Check if an error message indicates a worktree-related issue (missing worktree, no branch, etc.)
    30→ * This is used to show 'skipped' status instead of 'error' for tasks without worktrees.
    31→ *
    32→ * TODO: This string-based error detection is brittle. The API should ideally return typed error codes
    33→ * instead of relying on message parsing which may break with i18n or message changes.
    34→ */
    35→function isWorktreeRelatedError(errorMsg: string): boolean {
    36→  const lowerMsg = errorMsg.toLowerCase();
    37→  return lowerMsg.includes('worktree') ||
    38→         lowerMsg.includes('no branch') ||
    39→         lowerMsg.includes('not found');
    40→}
