    61→/**
    62→ * Dialog for creating Pull Requests for multiple tasks in bulk
    63→ * Shows progress tracking and results per task
    64→ */
    65→export function BulkPRDialog({
    66→  open,
    67→  tasks,
    68→  onOpenChange,
    69→  onComplete
    70→}: BulkPRDialogProps) {
    71→  const { t } = useTranslation(['taskReview', 'common', 'tasks']);
    72→
    73→  // Common options for all PRs
    74→  const [targetBranch, setTargetBranch] = useState('');
    75→  const [isDraft, setIsDraft] = useState(false);
    76→
    77→  // Progress tracking
    78→  const [step, setStep] = useState<'options' | 'creating' | 'results'>('options');
    79→  const [taskResults, setTaskResults] = useState<TaskPRResult[]>([]);
    80→  const [currentIndex, setCurrentIndex] = useState(0);
    81→  const isCancelledRef = useRef(false);
    82→
    83→  const prevOpenRef = useRef(open);
    84→
    85→  // Only reset when transitioning closed→open (not on tasks array changes during async operation)
    86→  useEffect(() => {
    87→    const wasOpen = prevOpenRef.current;
    88→    prevOpenRef.current = open;
    89→
    90→    if (open && !wasOpen) {
    91→      setTargetBranch('');
    92→      setIsDraft(false);
    93→      setStep('options');
    94→      setCurrentIndex(0);
    95→      isCancelledRef.current = false;
    96→      setTaskResults(tasks.map(task => ({
    97→        taskId: task.id,
    98→        taskTitle: task.title,
    99→        status: 'pending'
   100→      })));
   101→    }
   102→  }, [open, tasks]);
   103→
   104→  // Validation
   105→  const validateBranchName = useCallback((branch: string): string | null => {
   106→    if (!branch.trim()) return null; // Empty is OK, will use default
   107→    if (!/^[a-zA-Z0-9/_-]+$/.test(branch)) {
   108→      return t('taskReview:pr.errors.invalidBranchName');
   109→    }
   110→    return null;
   111→  }, [t]);
   112→
   113→  const handleCreatePRs = useCallback(async () => {
   114→    const branchError = validateBranchName(targetBranch);
   115→    if (branchError) {
   116→      return;
   117→    }
   118→
   119→    setStep('creating');
   120→    isCancelledRef.current = false;
   121→
   122→    const results: TaskPRResult[] = tasks.map(task => ({
   123→      taskId: task.id,
   124→      taskTitle: task.title,
   125→      status: 'pending' as const
   126→    }));
   127→    setTaskResults(results);
   128→
   129→    for (let i = 0; i < tasks.length; i++) {
   130→      if (isCancelledRef.current) break;
   131→
   132→      setCurrentIndex(i);
   133→
   134→      setTaskResults(prev => prev.map((r, idx) =>
   135→        idx === i ? { ...r, status: 'creating' as const } : r
   136→      ));
   137→
   138→      try {
   139→        const prResult = await window.electronAPI?.createWorktreePR(tasks[i].id, {
   140→          targetBranch: targetBranch || undefined,
   141→          draft: isDraft
   142→        });
   143→
   144→        if (isCancelledRef.current) break;
   145→
   146→        if (prResult?.success && prResult.data) {
   147→          const data = prResult.data;
   148→          setTaskResults(prev => prev.map((r, idx) =>
   149→            idx === i ? {
   150→              ...r,
   151→              status: data.success ? 'success' as const : 'error' as const,
   152→              result: data,
   153→              alreadyExists: data.alreadyExists,
   154→              error: data.success ? undefined : (data.error || t('taskReview:pr.errors.unknown'))
   155→            } : r
   156→          ));
   157→        } else {
   158→          const errorMsg = prResult?.error || '';
   159→          setTaskResults(prev => prev.map((r, idx) =>
   160→            idx === i ? {
   161→              ...r,
   162→              status: isWorktreeRelatedError(errorMsg) ? 'skipped' as const : 'error' as const,
   163→              error: isWorktreeRelatedError(errorMsg)
   164→                ? t('taskReview:bulkPR.noWorktree')
   165→                : (prResult?.error || t('taskReview:pr.errors.unknown'))
   166→            } : r
   167→          ));
   168→        }
   169→      } catch (err) {
   170→        if (isCancelledRef.current) break;
   171→
   172→        const errorMsg = err instanceof Error ? err.message : '';
   173→        setTaskResults(prev => prev.map((r, idx) =>
   174→          idx === i ? {
   175→            ...r,
   176→            status: isWorktreeRelatedError(errorMsg) ? 'skipped' as const : 'error' as const,
   177→            error: isWorktreeRelatedError(errorMsg)
   178→              ? t('taskReview:bulkPR.noWorktree')
   179→              : (err instanceof Error ? err.message : t('taskReview:pr.errors.unknown'))
   180→          } : r
   181→        ));
   182→      }
   183→    }
   184→
   185→    if (!isCancelledRef.current) {
   186→      setStep('results');
   187→    }
   188→  }, [tasks, targetBranch, isDraft, t, validateBranchName]);
   189→
   190→  const handleClose = () => {
   191→    isCancelledRef.current = true;
   192→    if (step === 'results' && onComplete) {
   193→      onComplete();
   194→    }
   195→    onOpenChange(false);
   196→  };
   197→
   198→  const handleOpenPR = (url: string) => {
   199→    if (window.electronAPI?.openExternal) {
   200→      window.electronAPI.openExternal(url);
   201→    }
   202→  };
   203→
   204→  // Calculate progress
   205→  const completedCount = taskResults.filter(r => r.status === 'success' || r.status === 'error' || r.status === 'skipped').length;
   206→  const successCount = taskResults.filter(r => r.status === 'success').length;
   207→  const errorCount = taskResults.filter(r => r.status === 'error').length;
   208→  const skippedCount = taskResults.filter(r => r.status === 'skipped').length;
   209→  const progress = tasks.length > 0 ? (completedCount / tasks.length) * 100 : 0;
   210→
   211→  return (
