   216→            <GitPullRequest className="h-5 w-5 text-primary" />
   217→            {t('taskReview:bulkPR.title')}
   218→          </DialogTitle>
   219→          <DialogDescription>
   220→            {step === 'options' && t('taskReview:bulkPR.description', { count: tasks.length })}
   221→            {step === 'creating' && t('taskReview:bulkPR.creating', { current: currentIndex + 1, total: tasks.length })}
   222→            {step === 'results' && (skippedCount > 0
   223→              ? t('taskReview:bulkPR.resultsDescriptionWithSkipped', { success: successCount, skipped: skippedCount, failed: errorCount })
   224→              : t('taskReview:bulkPR.resultsDescription', { success: successCount, failed: errorCount })
   225→            )}
   226→          </DialogDescription>
   227→        </DialogHeader>
   228→
   229→        {/* Options Step */}
   230→        {step === 'options' && (
   231→          <div className="space-y-4">
   232→            {/* Task List Preview */}
   233→            <div className="space-y-2">
   234→              <Label>{t('taskReview:bulkPR.tasksToProcess')}</Label>
   235→              <ScrollArea className="h-32 rounded-md border border-border p-2">
   236→                <div className="space-y-1">
   237→                  {tasks.map((task, idx) => (
   238→                    <div
   239→                      key={task.id}
   240→                      className="flex items-center gap-2 text-sm py-1 px-2 rounded hover:bg-muted/50"
   241→                    >
   242→                      <span className="text-muted-foreground">{idx + 1}.</span>
   243→                      <span className="truncate">{task.title}</span>
   244→                    </div>
   245→                  ))}
   246→                </div>
   247→              </ScrollArea>
   248→            </div>
