    56→const taskStatusChangeListeners = new Set<(taskId: string, oldStatus: TaskStatus | undefined, newStatus: TaskStatus) => void>();
    57→
    58→/**
    59→ * Notify all registered listeners when a task status changes
    60→ */
    61→function notifyTaskStatusChange(taskId: string, oldStatus: TaskStatus | undefined, newStatus: TaskStatus): void {
    62→  for (const listener of taskStatusChangeListeners) {
    63→    try {
    64→      listener(taskId, oldStatus, newStatus);
    65→    } catch (error) {
    66→      console.error('[TaskStore] Error in task status change listener:', error);
    67→    }
    68→  }
    69→}
