    71→/**
    72→ * Helper to update a single task efficiently.
    73→ * Uses slice instead of map to avoid iterating all tasks.
    74→ */
    75→function updateTaskAtIndex(tasks: Task[], index: number, updater: (task: Task) => Task): Task[] {
    76→  if (index < 0 || index >= tasks.length) return tasks;
    77→
    78→  const updatedTask = updater(tasks[index]);
    79→
    80→  // If the task reference didn't change, return original array
    81→  if (updatedTask === tasks[index]) {
    82→    return tasks;
    83→  }
    84→
    85→  // Create new array with only the changed task replaced
    86→  const newTasks = [...tasks];
    87→  newTasks[index] = updatedTask;
    88→
    89→  return newTasks;
    90→}
