    23→/**
    24→ * Validate keyboard shortcut data structure
    25→ * Returns true if valid, false if invalid
    26→ */
    27→function validateShortcuts(shortcuts: unknown): shortcuts is Record<KeyboardShortcutAction, KeyCombination> {
    28→  if (!shortcuts || typeof shortcuts !== 'object' || Array.isArray(shortcuts)) {
    29→    return false;
    30→  }
    31→
    32→  // Check that all required actions exist
    33→  const requiredActions: KeyboardShortcutAction[] = [
    34→    'commandPalette',
    35→    'quickActions',
    36→    'createTask',
    37→    'batchQA',
    38→    'batchStatusUpdate'
    39→  ];
    40→
    41→  for (const action of requiredActions) {
    42→    if (!(action in shortcuts) || typeof shortcuts[action as keyof typeof shortcuts] !== 'string') {
    43→      return false;
    44→    }
    45→  }
    46→
    47→  return true;
    48→}
