    50→/**
    51→ * Get the formatted key combination for display
    52→ * Converts "Cmd+K" to "⌘K" on macOS, "Ctrl+K" on Windows/Linux
    53→ */
    54→export function formatKeyCombination(keyCombination: KeyCombination): string {
    55→  const isMac = typeof window !== 'undefined' && window.navigator.platform.includes('Mac');
    56→
    57→  return keyCombination
    58→    .replace(/\+/g, isMac ? '' : '+')
    59→    .replace('Cmd', isMac ? '⌘' : 'Ctrl')
    60→    .replace('Ctrl', isMac ? '⌘' : 'Ctrl')
    61→    .replace('Shift', isMac ? '⇧' : 'Shift')
    62→    .replace('Alt', isMac ? '⌥' : 'Alt')
    63→    .replace('Meta', isMac ? '⌘' : 'Win');
    64→}
    65→
    66→/**
    67→ * Parse a keyboard event into a key combination string
    68→ * Handles platform differences (Cmd vs Ctrl)
    69→ */
    70→export function parseKeyboardEvent(event: KeyboardEvent): KeyCombination {
    71→  const parts: string[] = [];
    72→
    73→  if (event.metaKey) parts.push('Cmd');
    74→  if (event.ctrlKey) parts.push('Ctrl');
    75→  if (event.shiftKey) parts.push('Shift');
    76→  if (event.altKey) parts.push('Alt');
    77→
    78→  // Handle special keys
    79→  const key = event.key;
    80→  if (key === ' ') {
    81→    parts.push('Space');
    82→  } else if (key.length === 1) {
    83→    // Single character key (letter, number, symbol)
    84→    parts.push(key.toUpperCase());
    85→  } else {
    86→    // Special key name (Escape, Enter, etc.)
    87→    parts.push(key);
    88→  }
    89→
    90→  return parts.join('+');
    91→}
    92→
    93→/**
    94→ * Check if a keyboard event matches a key combination
    95→ */
    96→export function matchesKeyCombination(event: KeyboardEvent, keyCombination: KeyCombination): boolean {
    97→  const eventCombination = parseKeyboardEvent(event);
    98→  return eventCombination === keyCombination;
    99→}
