   101→export const useKeyboardShortcutsStore = create<KeyboardShortcutsState>((set, get) => ({
   102→  shortcuts: DEFAULT_KEYBOARD_SHORTCUTS,
   103→  isLoading: false,
   104→  error: null,
   105→
   106→  setShortcuts: (shortcuts) => set({ shortcuts }),
   107→
   108→  updateShortcut: (action, keyCombination) =>
