   114→    })),
   115→
   116→  resetToDefaults: () => {
   117→    set({ shortcuts: DEFAULT_KEYBOARD_SHORTCUTS });
   118→    // Save to localStorage after reset
   119→    try {
   120→      localStorage.setItem(KEYBOARD_SHORTCUTS_KEY, JSON.stringify(DEFAULT_KEYBOARD_SHORTCUTS));
   121→    } catch (error) {
   122→      console.error('[KeyboardShortcutsStore] Failed to save defaults to localStorage:', error);
   123→    }
