   176→/**
   177→ * Register a keyboard shortcut handler
   178→ * Returns a cleanup function to remove the listener
   179→ */
   180→export function registerKeyboardShortcut(
   181→  action: KeyboardShortcutAction,
   182→  handler: (event: KeyboardEvent) => void,
   183→  options?: { preventDefault?: boolean }
   184→): () => void {
   185→  const handleKeyDown = (event: KeyboardEvent) => {
   186→    const store = useKeyboardShortcutsStore.getState();
   187→    const keyCombination = store.getShortcut(action);
   188→
   189→    if (matchesKeyCombination(event, keyCombination)) {
   190→      if (options?.preventDefault !== false) {
   191→        event.preventDefault();
   192→      }
   193→      handler(event);
   194→    }
   195→  };
   196→
   197→  window.addEventListener('keydown', handleKeyDown);
   198→
   199→  // Return cleanup function
   200→  return () => {
   201→    window.removeEventListener('keydown', handleKeyDown);
   202→  };
   203→}
   204→
   205→/**
   206→ * Batch register multiple keyboard shortcuts
   207→ * Returns a cleanup function to remove all listeners
   208→ */
   209→export function registerKeyboardShortcuts(
   210→  shortcuts: Partial<Record<KeyboardShortcutAction, (event: KeyboardEvent) => void>>,
   211→  options?: { preventDefault?: boolean }
   212→): () => void {
   213→  const cleanupFunctions: Array<() => void> = [];
   214→
   215→  for (const [action, handler] of Object.entries(shortcuts)) {
   216→    if (handler) {
   217→      const cleanup = registerKeyboardShortcut(
   218→        action as KeyboardShortcutAction,
   219→        handler,
   220→        options
   221→      );
   222→      cleanupFunctions.push(cleanup);
   223→    }
   224→  }
   225→
   226→  // Return cleanup function that removes all listeners
   227→  return () => {
   228→    for (const cleanup of cleanupFunctions) {
   229→      cleanup();
   230→    }
   231→  };
   232→}
