   262→  async startQAProcess(
   263→    taskId: string,
   264→    projectPath: string,
   265→    specId: string
   266→  ): Promise<void> {
   267→    // Ensure Python environment is ready before spawning process (prevents exit code 127 race condition)
   268→    const pythonStatus = await this.processManager.ensurePythonEnvReady('AgentManager');
   269→    if (!pythonStatus.ready) {
   270→      this.emit('error', taskId, `Python environment not ready: ${pythonStatus.error || 'initialization failed'}`);
   271→      return;
   272→    }
   273→
   274→    const autoBuildSource = await this.processManager.getAutoBuildSourcePath();
   275→
   276→    if (!autoBuildSource) {
   277→      this.emit('error', taskId, 'Auto-build source path not found. Please configure it in App Settings.');
   278→      return;
   279→    }
   280→
   281→    const runPath = path.join(autoBuildSource, 'run.py');
   282→
   283→    if (!existsSync(runPath)) {
   284→      this.emit('error', taskId, `Run script not found at: ${runPath}`);
   285→      return;
   286→    }
   287→
   288→    // Get combined environment variables
   289→    const combinedEnv = await this.processManager.getCombinedEnv(projectPath);
   290→
   291→    const args = [runPath, '--spec', specId, '--project-dir', projectPath, '--qa'];
   292→
   293→    await this.processManager.spawnProcess(taskId, autoBuildSource, args, combinedEnv, 'qa-process');
   294→  }
