    50→  // Tab state - initialized empty, loaded via IPC from main process for reliability
    51→  openProjectIds: [],
    52→  activeProjectId: null,
    53→  tabOrder: [],
    54→
    55→  setProjects: (projects) => set({ projects }),
    56→
    57→  addProject: (project) =>
    58→    set((state) => ({
    59→      projects: [...state.projects, project]
    60→    })),
    61→
    62→  removeProject: (projectId) =>
    63→    set((state) => {
    64→      const isSelectedProject = state.selectedProjectId === projectId;
    65→      // Clear localStorage if we're removing the currently selected project
    66→      if (isSelectedProject) {
    67→        localStorage.removeItem(LAST_SELECTED_PROJECT_KEY);
