     9→export interface RecentAction {
    10→  /** Unique identifier for this action instance */
    11→  id: string;
    12→  /** Type of action performed */
    13→  type: 'batch_qa' | 'batch_status_update' | 'create_task' | 'start_task' | 'stop_task';
    14→  /** Display label for the action */
    15→  label: string;
    16→  /** Timestamp when the action was performed */
    17→  timestamp: Date;
    18→  /** Number of items affected (for batch operations) */
    19→  itemCount?: number;
