   190→      return action.itemCount
   191→        ? `Batch QA (${action.itemCount} tasks)`
   192→        : 'Batch QA';
   193→    case 'batch_status_update':
   194→      return action.itemCount && action.targetStatus
   195→        ? `Update to ${action.targetStatus} (${action.itemCount} tasks)`
