     1→/**
     2→ * GitHub issue import IPC handlers
     3→ */
     4→
     5→import { ipcMain } from 'electron';
     6→import { IPC_CHANNELS } from '../../../shared/constants';
     7→import type { IPCResult, GitHubImportResult, Task } from '../../../shared/types';
     8→import { projectStore } from '../../project-store';
     9→import { AgentManager } from '../../agent';
    10→import { getGitHubConfig, githubFetch } from './utils';
    11→import { createSpecForIssue } from './spec-utils';
    12→
    13→/**
    14→ * Import multiple GitHub issues as tasks
    15→ */
    16→export function registerImportIssues(agentManager: AgentManager): void {
    17→  ipcMain.handle(
    18→    IPC_CHANNELS.GITHUB_IMPORT_ISSUES,
    19→    async (_, projectId: string, issueNumbers: number[]): Promise<IPCResult<GitHubImportResult>> => {
    20→      const project = projectStore.getProject(projectId);
    21→      if (!project) {
    22→        return { success: false, error: 'Project not found' };
    23→      }
    24→
    25→      const config = getGitHubConfig(project);
    26→      if (!config) {
    27→        return { success: false, error: 'No GitHub token or repository configured' };
    28→      }
    29→
    30→      let imported = 0;
    31→      let failed = 0;
    32→      const errors: string[] = [];
    33→      const tasks: Task[] = [];
    34→
    35→      for (const issueNumber of issueNumbers) {
    36→        try {
    37→          // Fetch issue details
    38→          const issue = await githubFetch(
    39→            config.token,
    40→            `/repos/${config.repo}/issues/${issueNumber}`
    41→          ) as {
    42→            number: number;
    43→            title: string;
    44→            body?: string;
    45→            labels: Array<{ name: string }>;
    46→            html_url: string;
    47→          };
    48→
    49→          // Build description with metadata
    50→          const labelNames = issue.labels.map(l => l.name);
    51→          const labelsString = labelNames.join(', ');
    52→          const description = `# ${issue.title}
    53→
    54→**GitHub Issue:** [#${issue.number}](${issue.html_url})
    55→${labelsString ? `**Labels:** ${labelsString}` : ''}
    56→
    57→## Description
    58→
    59→${issue.body || 'No description provided.'}
    60→`;
    61→
    62→          // Create spec directory and files (with coordinated numbering)
    63→          const specData = await createSpecForIssue(
    64→            project,
    65→            issue.number,
    66→            issue.title,
    67→            description,
    68→            issue.html_url,
    69→            labelNames,
    70→            project.settings?.mainBranch  // Pass project's configured main branch
    71→          );
    72→
    73→          // Start spec creation with the existing spec directory
    74→          agentManager.startSpecCreation(
    75→            specData.specId,
    76→            project.path,
    77→            specData.taskDescription,
    78→            specData.specDir,
    79→            specData.metadata
    80→          );
    81→
    82→          imported++;
    83→        } catch (err) {
    84→          failed++;
    85→          errors.push(
    86→            `Failed to import #${issueNumber}: ${err instanceof Error ? err.message : 'Unknown error'}`
    87→          );
    88→        }
    89→      }
    90→
    91→      return {
    92→        success: true,
    93→        data: {
    94→          success: failed === 0,
    95→          imported,
    96→          failed,
    97→          errors: errors.length > 0 ? errors : undefined,
    98→          tasks
    99→        }
   100→      };
   101→    }
   102→  );
   103→}
   104→
   105→/**
   106→ * Register all import-related handlers
   107→ */
   108→export function registerImportHandlers(agentManager: AgentManager): void {
   109→  registerImportIssues(agentManager);
   110→}
