     1→import { useRef, useEffect, useCallback, useState } from 'react';
     2→import { Loader2, AlertCircle } from 'lucide-react';
     3→import { ScrollArea } from '../../ui/scroll-area';
     4→import { IssueListItem } from './IssueListItem';
     5→import { EmptyState } from './EmptyStates';
     6→import { IssueListSkeleton } from '../../skeletons/IssueListSkeleton';
     7→import type { IssueListProps } from '../types';
     8→import { useTranslation } from 'react-i18next';
     9→
    10→export function IssueList({
    11→  issues,
    12→  selectedIssueNumber,
    13→  isLoading,
    14→  isLoadingMore,
    15→  hasMore,
    16→  error,
    17→  onSelectIssue,
    18→  onInvestigate,
    19→  onQuickCreate,
    20→  onLoadMore
    21→}: IssueListProps) {
    22→  const { t } = useTranslation('common');
    23→  const loadMoreTriggerRef = useRef<HTMLDivElement>(null);
    24→  const [viewportElement, setViewportElement] = useState<HTMLDivElement | null>(null);
    25→
    26→  // Intersection Observer for infinite scroll
    27→  const handleIntersection = useCallback((entries: IntersectionObserverEntry[]) => {
    28→    const [entry] = entries;
    29→    if (entry.isIntersecting && hasMore && !isLoadingMore && !isLoading && onLoadMore) {
    30→      onLoadMore();
    31→    }
    32→  }, [hasMore, isLoadingMore, isLoading, onLoadMore]);
    33→
    34→  useEffect(() => {
    35→    const trigger = loadMoreTriggerRef.current;
    36→    if (!trigger || !onLoadMore || !viewportElement) return;
    37→
    38→    const observer = new IntersectionObserver(handleIntersection, {
    39→      root: viewportElement,
    40→      rootMargin: '100px',
    41→      threshold: 0
    42→    });
    43→
    44→    observer.observe(trigger);
    45→
    46→    return () => {
    47→      observer.disconnect();
    48→    };
    49→  }, [handleIntersection, onLoadMore, viewportElement]);
    50→
    51→  // Only show blocking error view when no issues are loaded
    52→  // Load-more errors are shown inline near the load-more trigger
    53→  if (error && issues.length === 0) {
    54→    return (
    55→      <div className="p-4 bg-destructive/10 border-b border-destructive/30">
    56→        <div className="flex items-center gap-2 text-sm text-destructive">
    57→          <AlertCircle className="h-4 w-4" />
    58→          {error}
    59→        </div>
    60→      </div>
    61→    );
    62→  }
    63→
    64→  if (isLoading && issues.length === 0) {
    65→    return (
    66→      <ScrollArea className="flex-1">
    67→        <div className="p-2">
    68→          <IssueListSkeleton count={5} />
    69→        </div>
    70→      </ScrollArea>
    71→    );
    72→  }
    73→
    74→  if (issues.length === 0) {
    75→    return <EmptyState message="No issues found" />;
    76→  }
    77→
    78→  return (
    79→    <ScrollArea className="flex-1" onViewportRef={setViewportElement}>
    80→      <div className="p-2 space-y-1">
    81→        {issues.map((issue) => (
    82→          <IssueListItem
    83→            key={issue.id}
    84→            issue={issue}
    85→            isSelected={selectedIssueNumber === issue.number}
    86→            onClick={() => onSelectIssue(issue.number)}
    87→            onInvestigate={() => onInvestigate(issue)}
    88→            onQuickCreate={onQuickCreate ? () => onQuickCreate(issue) : undefined}
    89→          />
    90→        ))}
    91→
    92→        {/* Load more trigger / Loading indicator */}
    93→        {onLoadMore && (
    94→          <div ref={loadMoreTriggerRef} className="py-4 flex flex-col items-center gap-2">
    95→            {/* Inline error for load-more failures (when issues are already loaded) */}
    96→            {error && issues.length > 0 && (
    97→              <div className="flex items-center gap-2 text-sm text-destructive">
    98→                <AlertCircle className="h-4 w-4" />
    99→                {error}
   100→              </div>
   101→            )}
   102→            {isLoadingMore ? (
   103→              <div className="flex items-center gap-2 text-muted-foreground">
   104→                <Loader2 className="h-4 w-4 animate-spin" />
   105→                <span className="text-sm">{t('issues.loadingMore', 'Loading more...')}</span>
   106→              </div>
   107→            ) : hasMore ? (
   108→              <span className="text-xs text-muted-foreground opacity-50">
   109→                {t('issues.scrollForMore', 'Scroll for more')}
   110→              </span>
   111→            ) : issues.length > 0 ? (
   112→              <span className="text-xs text-muted-foreground opacity-50">
   113→                {t('issues.allLoaded', 'All issues loaded')}
   114→              </span>
   115→            ) : null}
   116→          </div>
   117→        )}
   118→      </div>
   119→    </ScrollArea>
   120→  );
   121→}
   122→

