    25→
    26→interface QuickActionsState {
    27→  recentActions: RecentAction[];
    28→  isLoading: boolean;
    29→  error: string | null;
    30→
    31→  // Actions
    32→  addRecentAction: (action: Omit<RecentAction, 'id' | 'timestamp'>) => void;
    33→  clearRecentActions: () => void;
    34→  removeRecentAction: (actionId: string) => void;
    35→  getRecentActions: () => RecentAction[];
    36→  setLoading: (loading: boolean) => void;
    37→  setError: (error: string | null) => void;
    38→  loadRecentActions: () => void;
    39→  saveRecentActions: () => boolean;
    40→}
    41→
    42→/**
    43→ * Maximum number of recent actions to store
    44→ */
    45→const MAX_RECENT_ACTIONS = 10;
    46→
    47→/**
    48→ * Validate recent actions data structure
    49→ */
    50→function validateRecentActions(data: unknown): data is RecentAction[] {
    51→  if (!Array.isArray(data)) {
    52→    return false;
    53→  }
    54→
    55→  return data.every((item): item is RecentAction => {
    56→    if (!item || typeof item !== 'object') {
    57→      return false;
    58→    }
    59→
    60→    const action = item as RecentAction;
    61→    return (
    62→      typeof action.id === 'string' &&
    63→      typeof action.type === 'string' &&
    64→      typeof action.label === 'string' &&
    65→      typeof action.timestamp === 'string' &&
    66→      (action.itemCount === undefined || typeof action.itemCount === 'number') &&
    67→      (action.targetStatus === undefined || typeof action.targetStatus === 'string') &&
    68→      (action.projectId === undefined || typeof action.projectId === 'string')
    69→    );
    70→  });
    71→}
    72→
    73→/**
    74→ * Convert stored data to RecentAction objects (convert timestamp strings to Dates)
    75→ */
    76→function hydrateRecentActions(data: RecentAction[]): RecentAction[] {
    77→  return data.map(action => ({
    78→    ...action,
    79→    timestamp: new Date(action.timestamp)
    80→  }));
    81→}
    82→
    83→/**
    84→ * Prepare recent actions for storage (convert Dates to ISO strings)
    85→ */
    86→function prepareForStorage(actions: RecentAction[]): RecentAction[] {
    87→  return actions.map(action => ({
    88→    ...action,
    89→    timestamp: action.timestamp.toISOString() as unknown as Date
    90→  })) as unknown as RecentAction[];
    91→}
