    93→export const useQuickActionsStore = create<QuickActionsState>((set, get) => ({
    94→  recentActions: [],
    95→  isLoading: false,
    96→  error: null,
    97→
    98→  addRecentAction: (action) =>
    99→    set((state) => {
   100→      const newAction: RecentAction = {
   101→        ...action,
   102→        id: `action-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
   103→        timestamp: new Date()
   104→      };
   105→
   106→      // Add to beginning of array, keep only MAX_RECENT_ACTIONS
   107→      const updatedActions = [newAction, ...state.recentActions].slice(0, MAX_RECENT_ACTIONS);
   108→
   109→      // Save to localStorage
   110→      try {
   111→        localStorage.setItem(RECENT_ACTIONS_KEY, JSON.stringify(prepareForStorage(updatedActions)));
   112→      } catch (error) {
   113→        console.error('[QuickActionsStore] Failed to save recent actions:', error);
   114→      }
   115→
   116→      return { recentActions: updatedActions };
   117→    }),
   118→
   119→  clearRecentActions: () => {
   120→    set({ recentActions: [] });
   121→    try {
   122→      localStorage.removeItem(RECENT_ACTIONS_KEY);
   123→    } catch (error) {
   124→      console.error('[QuickActionsStore] Failed to clear recent actions:', error);
   125→    }
   126→  },
   127→
   128→  removeRecentAction: (actionId) =>
   129→    set((state) => {
   130→      const updatedActions = state.recentActions.filter(a => a.id !== actionId);
   131→
   132→      try {
   133→        localStorage.setItem(RECENT_ACTIONS_KEY, JSON.stringify(prepareForStorage(updatedActions)));
   134→      } catch (error) {
   135→        console.error('[QuickActionsStore] Failed to save after removal:', error);
   136→      }
   137→
   138→      return { recentActions: updatedActions };
   139→    }),
   140→
   141→  getRecentActions: () => {
   142→    return get().recentActions;
