   151→      const stored = localStorage.getItem(RECENT_ACTIONS_KEY);
   152→      if (stored) {
   153→        const parsed = JSON.parse(stored);
   154→
   155→        if (validateRecentActions(parsed)) {
   156→          const hydrated = hydrateRecentActions(parsed);
   157→          set({ recentActions: hydrated });
   158→        } else {
   159→          console.warn('[QuickActionsStore] Invalid recent actions data, resetting to empty');
   160→          set({ recentActions: [] });
   161→        }
   162→      } else {
   163→        set({ recentActions: [] });
   164→      }
   165→    } catch (error) {
   166→      console.error('[QuickActionsStore] Failed to load recent actions:', error);
   167→      set({ recentActions: [] });
   168→    }
   169→  },
   170→
   171→  saveRecentActions: () => {
   172→    try {
   173→      const state = get();
   174→      localStorage.setItem(RECENT_ACTIONS_KEY, JSON.stringify(prepareForStorage(state.recentActions)));
   175→      return true;
   176→    } catch (error) {
   177→      console.error('[QuickActionsStore] Failed to save recent actions:', error);
   178→      return false;
