   219→export function getTimeAgo(timestamp: Date): string {
   220→  const now = new Date();
   221→  const diffMs = now.getTime() - timestamp.getTime();
   222→  const diffSecs = Math.floor(diffMs / 1000);
   223→  const diffMins = Math.floor(diffSecs / 60);
   224→  const diffHours = Math.floor(diffMins / 60);
   225→  const diffDays = Math.floor(diffHours / 24);
   226→
   227→  if (diffSecs < 60) {
   228→    return 'just now';
   229→  } else if (diffMins < 60) {
   230→    return `${diffMins}m ago`;
   231→  } else if (diffHours < 24) {
   232→    return `${diffHours}h ago`;
   233→  } else if (diffDays < 7) {
   234→    return `${diffDays}d ago`;
   235→  } else {
   236→    return timestamp.toLocaleDateString();
   237→  }
   238→}
