     7→interface KeyboardShortcutsState {
     8→  shortcuts: Record<KeyboardShortcutAction, KeyCombination>;
     9→  isLoading: boolean;
    10→  error: string | null;
    11→
    12→  // Actions
    13→  setShortcuts: (shortcuts: Record<KeyboardShortcutAction, KeyCombination>) => void;
    14→  updateShortcut: (action: KeyboardShortcutAction, keyCombination: KeyCombination) => void;
    15→  resetToDefaults: () => void;
