   101→export const useKeyboardShortcutsStore = create<KeyboardShortcutsState>((set, get) => ({
   102→  shortcuts: DEFAULT_KEYBOARD_SHORTCUTS,
   103→  isLoading: false,
   104→  error: null,
   105→
   106→  setShortcuts: (shortcuts) => set({ shortcuts }),
   107→
   108→  updateShortcut: (action, keyCombination) =>
   109→    set((state) => ({
   110→      shortcuts: {
   111→        ...state.shortcuts,
   112→        [action]: keyCombination
   113→      }
   114→    })),
   115→
   116→  resetToDefaults: () => {
   117→    set({ shortcuts: DEFAULT_KEYBOARD_SHORTCUTS });
   118→    // Save to localStorage after reset
   119→    try {
   120→      localStorage.setItem(KEYBOARD_SHORTCUTS_KEY, JSON.stringify(DEFAULT_KEYBOARD_SHORTCUTS));
   121→    } catch (error) {
   122→      console.error('[KeyboardShortcutsStore] Failed to save defaults to localStorage:', error);
   123→    }
   124→  },
   125→
   126→  getShortcut: (action) => {
   127→    const state = get();
   128→    return state.shortcuts[action] || DEFAULT_KEYBOARD_SHORTCUTS[action];
   129→  },
   130→
   131→  setLoading: (isLoading) => set({ isLoading }),
   132→
   133→  setError: (error) => set({ error }),
   134→
   135→  loadShortcuts: () => {
   136→    try {
   137→      const stored = localStorage.getItem(KEYBOARD_SHORTCUTS_KEY);
   138→      if (stored) {
   139→        const parsed = JSON.parse(stored);
   140→        if (validateShortcuts(parsed)) {
   141→          set({ shortcuts: parsed });
   142→        } else {
   143→          console.warn('[KeyboardShortcutsStore] Invalid shortcuts in localStorage, using defaults');
   144→          set({ shortcuts: DEFAULT_KEYBOARD_SHORTCUTS });
   145→        }
   146→      } else {
   147→        set({ shortcuts: DEFAULT_KEYBOARD_SHORTCUTS });
   148→      }
   149→    } catch (error) {
   150→      console.error('[KeyboardShortcutsStore] Failed to load shortcuts from localStorage:', error);
   151→      set({ shortcuts: DEFAULT_KEYBOARD_SHORTCUTS, error: 'Failed to load keyboard shortcuts' });
   152→    }
   153→  },
   154→
   155→  saveShortcuts: () => {
   156→    try {
   157→      const state = get();
   158→      localStorage.setItem(KEYBOARD_SHORTCUTS_KEY, JSON.stringify(state.shortcuts));
   159→      return true;
   160→    } catch (error) {
   161→      console.error('[KeyboardShortcutsStore] Failed to save shortcuts to localStorage:', error);
   162→      set({ error: 'Failed to save keyboard shortcuts' });
   163→      return false;
   164→    }
   165→  }
   166→}));
