   168→/**
   169→ * Initialize keyboard shortcuts store
   170→ * Loads shortcuts from localStorage on app startup
   171→ */
   172→export function initializeKeyboardShortcuts(): void {
   173→  useKeyboardShortcutsStore.getState().loadShortcuts();
   174→}
